/**
* Computes the sine and cosine integrals.
*
* ## Method
*
* -   The integrals are approximated by rational functions.
*
* -   For \\( x > 8 \\), auxiliary functions \\( f(x) \\) and \\( g(x) \\) are employed such that
*
*     ```tex
*     \operatorname{Ci}(x) = f(x) \sin(x) - g(x) \cos(x) \\
*     \operatorname{Si}(x) = \pi/2 - f(x) \cos(x) - g(x) \sin(x)
*     ```
*
* ## Notes
*
* -   Absolute error on test interval \\( \[0,50\] \\), except relative when greater than \\( 1 \\):
*
*     | arithmetic | function    | # trials | peak    | rms     |
*     |:----------:|:-----------:|:--------:|:-------:|:-------:|
*     | IEEE       | Si          | 30000    | 4.4e-16 | 7.3e-17 |
*     | IEEE       | Ci          | 30000    | 6.9e-16 | 5.1e-17 |
*
* @param x     input value
* @param si    output pointer for sine integral
* @param ci    output pointer for cosine integral
*
* @example
* double si;
* double ci;
*
* stdlib_base_sici( 3.0, &si, &ci );
*/
void stdlib_base_sici( const double x, double *si, double *ci ) {
	double sgn;
	double ax;
	double c;
	double f;
	double g;
	double s;
	double z;

	if ( stdlib_base_is_nan( x ) ) {
		*si = 0.0 / 0.0; // NaN
		*ci = 0.0 / 0.0; // NaN
		return;
	}

	if ( x < 0.0 ) {
		sgn = -1.0;
		ax = -x;
	} else {
		sgn = 1.0;
		ax = x;
	}

	if ( ax == 0.0 ) {
		*si = 0.0;
		*ci = STDLIB_CONSTANT_FLOAT64_NINF;
		return;
	}

	if ( ax > 1.0e9 ) {
		if ( stdlib_base_is_infinite( ax ) ) {
			if ( sgn < 0.0 ) {
				*si = -STDLIB_CONSTANT_FLOAT64_HALF_PI;
				*ci = 0.0 / 0.0; // NaN
			} else {
				*si = STDLIB_CONSTANT_FLOAT64_HALF_PI;
				*ci = 0.0;
			}
			return;
		}
		stdlib_base_sincos( ax, &s, &c );
		*si = STDLIB_CONSTANT_FLOAT64_HALF_PI - ( c / ax );
		*ci = s / ax;
		if ( sgn < 0.0 ) {
			*si = -*si;
		}
		return;
	}

	if ( ax > 4.0 ) {
		stdlib_base_sincos( ax, &s, &c );
		z = 1.0 / ( ax * ax );

		if ( ax < 8.0 ) {
			f = polyval_fn4( z ) / ( ax * polyval_fd4( z ) );
			g = z * polyval_gn4( z ) / polyval_gd4( z );
		} else {
			f = polyval_fn8( z ) / ( ax * polyval_fd8( z ) );
			g = z * polyval_gn8( z ) / polyval_gd8( z );
		}

		*si = STDLIB_CONSTANT_FLOAT64_HALF_PI - ( f * c ) - ( g * s );
		if ( sgn < 0.0 ) {
			*si = -*si;
		}
		*ci = ( f * s ) - ( g * c );
		return;
	}

	z = ax * ax;
	s = ax * polyval_sn( z ) / polyval_sd( z );
	c = z * polyval_cn( z ) / polyval_cd( z );

	if ( sgn < 0.0 ) {
		s = -s;
	}

	*si = s;
	*ci = STDLIB_CONSTANT_FLOAT64_EULERGAMMA + stdlib_base_ln( ax ) + c;
}
